from functools import wraps

def log(fn):
    @wraps(fn)
    def wrapper(*args, **kwargs):
        print(f'calling {fn.__name__}')
        return fn(*args, **kwargs)
    return wrapper

def repeat(n):
    def deco(fn):
        @wraps(fn)
        def wrapper(*a, **kw):
            for _ in range(n):
                fn(*a, **kw)
        return wrapper
    return deco

